/**
 * Translations for <FormSelect>/<FormSelectMultiple>.
 *
 * Deliberately NOT part of the auto-generated `../../strings/translations.ts`
 * (that file is regenerated by the fireback language & translation manager
 * from the app's own `strings-*.yml` catalog and shouldn't be hand-edited,
 * and pulling from it means every consumer of FormSelect - including ones
 * outside this app entirely - inherits that whole catalog and its `useS`/
 * locale-context wiring just to render a select box). Keeping this
 * component's strings local to its own folder, resolved from a plain
 * `locale` prop instead, is what lets FormSelect be used standalone.
 */

import { createContext, useContext } from "react";

/**
 * Optional escape hatch from passing `locale` to every single `<FormSelect>`
 * by hand: mount `<FormSelectLocaleProvider value={locale}>` once near your
 * app's root, and any `<FormSelect>` under it that doesn't set its own
 * `locale` prop picks this up instead. Left unmounted,
 * `useFormSelectLocale()` simply returns `undefined` and
 * `resolveFormSelectStrings` falls back to its own default ("en") exactly as
 * if this context didn't exist - so FormSelect never *requires* it, and
 * still doesn't depend on the app's own `useS`/locale-context machinery, or
 * any particular way of tracking "the current locale", to work standalone.
 */
const FormSelectLocaleContext = createContext<string | undefined>(undefined);

export const FormSelectLocaleProvider = FormSelectLocaleContext.Provider;

/** The locale set by an ancestor `<FormSelectLocaleProvider>`, if any. */
export function useFormSelectLocale(): string | undefined {
  return useContext(FormSelectLocaleContext);
}

export interface FormSelectStrings {
  /** Shown instead of the control when no `querySource` was given. */
  noQuerySourceToRender: string;
  /** aria-label on the native <select> fallback (`convertToNative`). */
  defaultSelectExample: string;
  /** First, unselectable option of the native <select> fallback. */
  selectPlaceholder: string;
  /** Placeholder text of the react-select search box. */
  searchPlaceholder: string;
  /** react-select's "nothing matched" message. */
  noOptions: string;
}

