/** Every locale FormSelect ships copy for out of the box, keyed by 2-char code. */
export const formSelectStrings: Record<string, FormSelectStrings> = {
  en,
  de,
  es,
  fa,
  ru,
  pl,
  fr,
};

/** Locales this component ships copy for. */
export const FORM_SELECT_LOCALES = Object.keys(
  formSelectStrings,
) as Array<keyof typeof formSelectStrings>;

/**
 * Resolves the strings FormSelect should render: the built-in copy for
 * `locale` (falling back to English for an unset/unrecognized 2-char code),
 * with `overrides` shallow-merged on top so a caller can replace one key or
 * hand in a whole custom, fully-typed translation map - `Partial` keeps
 * every key optional while still catching a typo'd key or wrong value type
 * at compile time. No `useS`/locale-context dependency involved.
 */
export function resolveFormSelectStrings(
  locale?: string,
  overrides?: Partial<FormSelectStrings>,
): FormSelectStrings {
  const base =
    formSelectStrings[(locale || "en").toLowerCase()] ?? formSelectStrings.en;
  return overrides ? { ...base, ...overrides } : base;
}
